// Detect if this email is a bank e-statement with a PDF attachment
const item = $input.first();
const { from, subject, text, html } = item.json;

const body = (text || html || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
const sender = (from || '').toLowerCase();
const subjectLow = (subject || '').toLowerCase();

// Check for PDF attachment keys
const allKeys = Object.keys(item.json);
const attachmentKey = allKeys.find(k => k.startsWith('attachment_') && item.json[k]?.mimeType === 'application/pdf');

if (!attachmentKey) {
  return [{ json: { skip: true, reason: 'No PDF attachment found' } }];
}

// Statement email keywords
const statementKeywords = /(e-?statement|laporan|rekening koran|tagihan|billing statement|account statement)/i;
if (!statementKeywords.test(subjectLow) && !statementKeywords.test(body)) {
  return [{ json: { skip: true, reason: 'Not a statement email', subject } }];
}

// Detect bank type
let bankType = null;
if (sender.includes('bca') || subjectLow.includes('bca') || body.includes('BCA')) bankType = 'BCA';
else if (sender.includes('jenius') || subjectLow.includes('jenius')) bankType = 'Jenius';
else if (sender.includes('uob') || subjectLow.includes('uob')) bankType = 'UOB';
else if (sender.includes('bri') || subjectLow.includes('bri')) bankType = 'BRI';

if (!bankType) {
  return [{ json: { skip: true, reason: 'Unknown bank in statement email', subject } }];
}

// Extract statement month (YYYY-MM)
function extractStatementMonth(text) {
  const monthNames = { januari:1, january:1, februari:2, february:2, maret:3, march:3,
    april:4, mei:5, may:5, juni:6, june:6, juli:7, july:7, agustus:8, august:8,
    september:9, oktober:10, october:10, november:11, desember:12, december:12,
    jan:1, feb:2, mar:3, apr:4, jun:6, jul:7, agu:8, aug:8, sep:9, okt:10, oct:10, nov:11, des:12, dec:12 };

  // Pattern: Month YYYY or YYYY-MM or MM/YYYY
  const patterns = [
    /(\w+)\s+(\d{4})/,  // Januari 2025
    /(\d{4})-(\d{2})/,  // 2025-01
    /(\d{2})\/(\d{4})/,  // 01/2025
  ];

  for (const p of patterns) {
    const m = text.match(p);
    if (m) {
      if (p.source.startsWith('(\\w+)')) {
        const month = monthNames[(m[1] || '').toLowerCase()];
        if (month) return `${m[2]}-${String(month).padStart(2, '0')}`;
      } else if (p.source.startsWith('(\\d{4})')) {
        return `${m[1]}-${m[2]}`;
      } else {
        return `${m[2]}-${m[1]}`;
      }
    }
  }

  // Default to previous month
  const d = new Date();
  d.setMonth(d.getMonth() - 1);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
}

const statementMonth = extractStatementMonth(subjectLow + ' ' + body.slice(0, 500));
const attachment = item.json[attachmentKey];

return [{
  json: {
    skip: false,
    bankType,
    statementMonth,
    attachmentKey,
    fileName: attachment.name || `${bankType}_${statementMonth}.pdf`,
    mimeType: attachment.mimeType,
    data: attachment.content, // base64 encoded PDF
  }
}];
